=== FILE: axi4_lite_regs.v ===
`timescale 1ns / 1ps
// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md (holding registers,
// READY from state only, one outstanding transaction per direction,
// SLVERR for unmapped addresses, synchronous active-low reset).
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;
    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg                  w_held_q;
    reg [ADDR_WIDTH-1:0] aw_addr_q;   // datapath, not reset
    reg [DATA_WIDTH-1:0] w_data_q;    // datapath, not reset
    reg [STRB_WIDTH-1:0] w_strb_q;    // datapath, not reset
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [DATA_WIDTH-1:0] rdata_q;
    reg [DATA_WIDTH-1:0] reg0_q;
    reg [DATA_WIDTH-1:0] reg1_q;
    reg [DATA_WIDTH-1:0] reg2_q;
    reg [DATA_WIDTH-1:0] reg3_q;

    // Next state
    reg                  aw_held_d;
    reg                  w_held_d;
    reg                  bvalid_d;
    reg [1:0]            bresp_d;
    reg                  rvalid_d;
    reg [1:0]            rresp_d;
    reg [DATA_WIDTH-1:0] rdata_d;
    reg [DATA_WIDTH-1:0] reg0_d;
    reg [DATA_WIDTH-1:0] reg1_d;
    reg [DATA_WIDTH-1:0] reg2_d;
    reg [DATA_WIDTH-1:0] reg3_d;

    // ------------------------------------------------------------------
    // READY is a function of state only
    // ------------------------------------------------------------------
    wire awready = !aw_held_q && !bvalid_q;
    wire wready  = !w_held_q && !bvalid_q;
    wire arready = !rvalid_q;

    wire aw_hs = s_axil_awvalid && awready;
    wire w_hs  = s_axil_wvalid && wready;
    wire ar_hs = s_axil_arvalid && arready;

    // The write fires on the edge that completes the AW/W pair
    wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held_q ? w_data_q : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

    // Address decode: mapped when word aligned and below 0x10
    wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    wire [1:0] wr_index = wr_addr[3:2];
    wire [1:0] rd_index = s_axil_araddr[3:2];

    // Byte mask from the strobes
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wr_mask
            assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Read select
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rd_sel;
    always @(*) begin
        case (rd_index)
            2'd0:    rd_sel = reg0_q;
            2'd1:    rd_sel = reg1_q;
            2'd2:    rd_sel = reg2_q;
            2'd3:    rd_sel = reg3_q;
            default: rd_sel = {DATA_WIDTH{1'b0}};
        endcase
    end

    // ------------------------------------------------------------------
    // Next-state logic
    // ------------------------------------------------------------------
    always @(*) begin
        aw_held_d = aw_held_q;
        w_held_d  = w_held_q;
        bvalid_d  = bvalid_q;
        bresp_d   = bresp_q;
        rvalid_d  = rvalid_q;
        rresp_d   = rresp_q;
        rdata_d   = rdata_q;
        reg0_d    = reg0_q;
        reg1_d    = reg1_q;
        reg2_d    = reg2_q;
        reg3_d    = reg3_q;

        // Write channel
        if (bvalid_q && s_axil_bready) begin
            bvalid_d = 1'b0;
        end
        if (aw_hs && !do_write) begin
            aw_held_d = 1'b1;
        end
        if (w_hs && !do_write) begin
            w_held_d = 1'b1;
        end
        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
            bvalid_d  = 1'b1;
            bresp_d   = wr_mapped ? RESP_OKAY : RESP_SLVERR;
            if (wr_mapped) begin
                case (wr_index)
                    2'd0:    reg0_d = (reg0_q & ~wr_mask) | (wr_data & wr_mask);
                    2'd1:    reg1_d = (reg1_q & ~wr_mask) | (wr_data & wr_mask);
                    2'd2:    reg2_d = (reg2_q & ~wr_mask) | (wr_data & wr_mask);
                    2'd3:    reg3_d = (reg3_q & ~wr_mask) | (wr_data & wr_mask);
                    default: begin end
                endcase
            end
        end

        // Read channel
        if (rvalid_q && s_axil_rready) begin
            rvalid_d = 1'b0;
        end
        if (ar_hs) begin
            rvalid_d = 1'b1;
            rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
            rdata_d  = rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
        end
    end

    // ------------------------------------------------------------------
    // State registers (synchronous, active-low reset)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            w_held_q  <= 1'b0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rresp_q   <= RESP_OKAY;
            rdata_q   <= {DATA_WIDTH{1'b0}};
            reg0_q    <= {DATA_WIDTH{1'b0}};
            reg1_q    <= {DATA_WIDTH{1'b0}};
            reg2_q    <= {DATA_WIDTH{1'b0}};
            reg3_q    <= {DATA_WIDTH{1'b0}};
        end else begin
            aw_held_q <= aw_held_d;
            w_held_q  <= w_held_d;
            bvalid_q  <= bvalid_d;
            bresp_q   <= bresp_d;
            rvalid_q  <= rvalid_d;
            rresp_q   <= rresp_d;
            rdata_q   <= rdata_d;
            reg0_q    <= reg0_d;
            reg1_q    <= reg1_d;
            reg2_q    <= reg2_d;
            reg3_q    <= reg3_d;
        end
    end

    // Holding registers: datapath with load enable, guarded by the held flags
    always @(posedge aclk) begin
        if (aw_hs && !do_write) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs && !do_write) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = awready;
    assign s_axil_wready  = wready;
    assign s_axil_arready = arready;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (for a SymbiYosys proof setup)
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Manager assumptions
    always @(*) begin
        if (!f_past_valid) assume(!aresetn);
        if (!aresetn) assume(!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready))
                assume(s_axil_awvalid && $stable(s_axil_awaddr));
            if ($past(s_axil_wvalid && !s_axil_wready))
                assume(s_axil_wvalid && $stable(s_axil_wdata) && $stable(s_axil_wstrb));
            if ($past(s_axil_arvalid && !s_axil_arready))
                assume(s_axil_arvalid && $stable(s_axil_araddr));
        end
    end

    // State invariants
    always @(*) begin
        if (f_past_valid) begin
            assert(!(aw_held_q && w_held_q));
            if (bvalid_q) assert(!aw_held_q && !w_held_q);
            assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
            if (rvalid_q && (rresp_q == RESP_SLVERR))
                assert(rdata_q == {DATA_WIDTH{1'b0}});
        end
    end

    // Handshake and response properties
    always @(posedge aclk) begin
        if (f_past_valid && !$past(aresetn))
            assert(!s_axil_bvalid && !s_axil_rvalid);
        if (f_past_valid && $past(aresetn)) begin
            if ($past(s_axil_bvalid && !s_axil_bready))
                assert(s_axil_bvalid && $stable(s_axil_bresp));
            if ($past(s_axil_rvalid && !s_axil_rready))
                assert(s_axil_rvalid && $stable(s_axil_rresp) && $stable(s_axil_rdata));
            if (!$past(s_axil_bvalid))
                assert(s_axil_bvalid == $past(do_write));
            if (!$past(s_axil_rvalid))
                assert(s_axil_rvalid == $past(ar_hs));
            if ($past(do_write))
                assert(s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
            if ($past(ar_hs))
                assert(s_axil_rresp == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR));
        end
    end

    // Covers
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn)) begin
            cover($past(s_axil_bvalid && s_axil_bready) && ($past(s_axil_bresp) == RESP_OKAY));
            cover($past(s_axil_rvalid && s_axil_rready) && ($past(s_axil_rresp) == RESP_OKAY));
            cover($past(aw_held_q) && $past(do_write));
            cover($past(w_held_q) && $past(do_write));
        end
    end
`endif

endmodule
=== END FILE ===
=== FILE: axi4_lite_regs_tb.v ===
`timescale 1ns / 1ps
// Self-checking testbench for axi4_lite_regs.
// Inputs are driven on the falling edge; handshakes are decided before the
// rising edge, so there is no race with the design.
`define CHECK(c, m) begin if (c) passed = passed + 1; else begin failed = failed + 1; $error("FAIL: %s (t=%0t)", m, $time); end end
`define CHECK_EQ(got, want, m) begin if ((got) === (want)) passed = passed + 1; else begin failed = failed + 1; $error("FAIL: %s: got %h expected %h (t=%0t)", m, got, want, $time); end end

module axi4_lite_regs_tb;

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    reg         aclk = 1'b0;
    reg         aresetn = 1'b0;
    reg  [3:0]  s_axil_awaddr = 4'h0;
    reg         s_axil_awvalid = 1'b0;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata = 32'h0;
    reg  [3:0]  s_axil_wstrb = 4'h0;
    reg         s_axil_wvalid = 1'b0;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready = 1'b0;
    reg  [3:0]  s_axil_araddr = 4'h0;
    reg         s_axil_arvalid = 1'b0;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready = 1'b0;

    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;
    reg [31:0] model [0:3];

    axi4_lite_regs dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    always #5 aclk = ~aclk;

    // Reference byte merge
    function [31:0] tb_merge;
        input [31:0] old_v;
        input [31:0] new_v;
        input [3:0]  strb;
        begin
            tb_merge = old_v;
            if (strb[0]) tb_merge[7:0]   = new_v[7:0];
            if (strb[1]) tb_merge[15:8]  = new_v[15:8];
            if (strb[2]) tb_merge[23:16] = new_v[23:16];
            if (strb[3]) tb_merge[31:24] = new_v[31:24];
        end
    endfunction

    // Reset for a number of cycles; entered and left at a falling edge.
    task do_reset;
        input integer cycles;
        begin
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            s_axil_arvalid = 1'b0;
            s_axil_bready  = 1'b0;
            s_axil_rready  = 1'b0;
            aresetn = 1'b0;
            repeat (cycles) begin
                @(negedge aclk);
                `CHECK(!s_axil_bvalid && !s_axil_rvalid, "reset: BVALID and RVALID must be low in reset")
            end
            aresetn = 1'b1;
            model[0] = 32'h0;
            model[1] = 32'h0;
            model[2] = 32'h0;
            model[3] = 32'h0;
            `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "reset: READYs must be high after reset")
            `CHECK(!s_axil_bvalid && !s_axil_rvalid, "reset: no response pending after reset")
        end
    endtask

    // One write. order: 0 AW and W together, 1 AW first, 2 W first.
    // gap: cycle index at which the second channel may be presented.
    // bdelay: 0 = BREADY high from the start, else BREADY low for bdelay
    // cycles after BVALID rises. Entered and left at a falling edge.
    task axi_write;
        input [3:0]   addr;
        input [31:0]  data;
        input [3:0]   strb;
        input integer order;
        input integer gap;
        input integer bdelay;
        reg aw_done;
        reg w_done;
        reg aw_fire;
        reg w_fire;
        reg [1:0] exp_resp;
        reg [1:0] held_resp;
        integer k;
        integer lat;
        begin
            exp_resp = (addr[1:0] == 2'b00) ? RESP_OKAY : RESP_SLVERR;
            aw_done = 1'b0;
            w_done  = 1'b0;
            k = 0;
            s_axil_bready = (bdelay == 0);
            while (!(aw_done && w_done) && (k < 50)) begin
                if (!aw_done && ((order != 2) || (w_done && (k >= gap)))) begin
                    s_axil_awvalid = 1'b1;
                    s_axil_awaddr  = addr;
                end
                if (!w_done && ((order != 1) || (aw_done && (k >= gap)))) begin
                    s_axil_wvalid = 1'b1;
                    s_axil_wdata  = data;
                    s_axil_wstrb  = strb;
                end
                #1;
                `CHECK(!s_axil_bvalid, "write: BVALID before both AW and W were accepted")
                if (aw_done && !w_done) begin
                    `CHECK(!s_axil_awready && s_axil_wready, "write: AW held so AWREADY low and WREADY high")
                end
                if (w_done && !aw_done) begin
                    `CHECK(s_axil_awready && !s_axil_wready, "write: W held so WREADY low and AWREADY high")
                end
                aw_fire = s_axil_awvalid && s_axil_awready;
                w_fire  = s_axil_wvalid && s_axil_wready;
                if (s_axil_awvalid) begin
                    `CHECK(aw_fire, "write: AW not accepted while the write side is idle")
                end
                if (s_axil_wvalid) begin
                    `CHECK(w_fire, "write: W not accepted while the write side is idle")
                end
                @(posedge aclk);
                if (aw_fire) aw_done = 1'b1;
                if (w_fire)  w_done  = 1'b1;
                @(negedge aclk);
                if (aw_fire) begin
                    s_axil_awvalid = 1'b0;
                    s_axil_awaddr  = 4'h0;
                end
                if (w_fire) begin
                    s_axil_wvalid = 1'b0;
                    s_axil_wdata  = 32'h0;
                    s_axil_wstrb  = 4'h0;
                end
                k = k + 1;
            end
            s_axil_awvalid = 1'b0;
            s_axil_wvalid  = 1'b0;
            `CHECK(aw_done && w_done, "write: AW/W handshake timed out")

            // Latency: 1 means BVALID is high at the first edge after the request
            lat = 1;
            while (!s_axil_bvalid && (lat < 5)) begin
                @(negedge aclk);
                lat = lat + 1;
            end
            `CHECK(s_axil_bvalid, "write: BVALID never rose")
            `CHECK(lat <= 2, "write: latency exceeds 2 cycles")
            `CHECK_EQ(s_axil_bresp, exp_resp, "write: BRESP")
            `CHECK(!s_axil_awready && !s_axil_wready, "write: AWREADY and WREADY must be low while B is pending")
            held_resp = s_axil_bresp;
            if (bdelay > 0) begin
                repeat (bdelay) begin
                    @(negedge aclk);
                    `CHECK(s_axil_bvalid, "write: BVALID dropped before BREADY")
                    `CHECK_EQ(s_axil_bresp, held_resp, "write: BRESP changed while stalled")
                    `CHECK(!s_axil_awready && !s_axil_wready, "write: READY high while B stalled")
                end
                s_axil_bready = 1'b1;
            end
            @(posedge aclk);
            @(negedge aclk);
            s_axil_bready = 1'b0;
            `CHECK(!s_axil_bvalid, "write: BVALID still high after the B handshake")
            `CHECK(s_axil_awready && s_axil_wready, "write: not ready for a new write the cycle after B")
            if (exp_resp == RESP_OKAY) begin
                model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
            end
        end
    endtask

    // One read. rdelay: 0 = RREADY high from the start, else RREADY low for
    // rdelay cycles after RVALID rises. Entered and left at a falling edge.
    task axi_read;
        input [3:0]   addr;
        input integer rdelay;
        reg [31:0] exp_data;
        reg [31:0] held_data;
        reg [1:0]  exp_resp;
        reg [1:0]  held_resp;
        reg ar_fire;
        reg ar_done;
        integer k;
        integer lat;
        begin
            exp_resp = (addr[1:0] == 2'b00) ? RESP_OKAY : RESP_SLVERR;
            exp_data = (addr[1:0] == 2'b00) ? model[addr[3:2]] : 32'h0;
            s_axil_rready  = (rdelay == 0);
            s_axil_arvalid = 1'b1;
            s_axil_araddr  = addr;
            ar_done = 1'b0;
            k = 0;
            while (!ar_done && (k < 50)) begin
                #1;
                `CHECK(!s_axil_rvalid, "read: RVALID before AR was accepted")
                ar_fire = s_axil_arvalid && s_axil_arready;
                `CHECK(ar_fire, "read: AR not accepted while the read side is idle")
                @(posedge aclk);
                if (ar_fire) ar_done = 1'b1;
                @(negedge aclk);
                k = k + 1;
            end
            s_axil_arvalid = 1'b0;
            s_axil_araddr  = 4'h0;
            `CHECK(ar_done, "read: AR handshake timed out")

            lat = 1;
            while (!s_axil_rvalid && (lat < 5)) begin
                @(negedge aclk);
                lat = lat + 1;
            end
            `CHECK(s_axil_rvalid, "read: RVALID never rose")
            `CHECK(lat <= 2, "read: latency exceeds 2 cycles")
            `CHECK_EQ(s_axil_rresp, exp_resp, "read: RRESP")
            `CHECK_EQ(s_axil_rdata, exp_data, "read: RDATA")
            `CHECK(!s_axil_arready, "read: ARREADY must be low while R is pending")
            held_data = s_axil_rdata;
            held_resp = s_axil_rresp;
            if (rdelay > 0) begin
                repeat (rdelay) begin
                    @(negedge aclk);
                    `CHECK(s_axil_rvalid, "read: RVALID dropped before RREADY")
                    `CHECK_EQ(s_axil_rdata, held_data, "read: RDATA changed while stalled")
                    `CHECK_EQ(s_axil_rresp, held_resp, "read: RRESP changed while stalled")
                    `CHECK(!s_axil_arready, "read: ARREADY high while R stalled")
                end
                s_axil_rready = 1'b1;
            end
            @(posedge aclk);
            @(negedge aclk);
            s_axil_rready = 1'b0;
            `CHECK(!s_axil_rvalid, "read: RVALID still high after the R handshake")
            `CHECK(s_axil_arready, "read: not ready for a new read the cycle after R")
        end
    endtask

    task read_all;
        begin
            axi_read(4'h0, 0);
            axi_read(4'h4, 0);
            axi_read(4'h8, 0);
            axi_read(4'hC, 0);
        end
    endtask

    // Watchdog: a hung run still ends with a failing verdict
    initial begin
        #200000;
        $error("FAIL: watchdog timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

    initial begin
        passed = 0;
        failed = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {64{8'h00}};
        model[0] = 32'h0;
        model[1] = 32'h0;
        model[2] = 32'h0;
        model[3] = 32'h0;

        // 1. Reset and reset values
        do_reset(3);
        read_all;

        // 2. Write then read every register
        axi_write(4'h0, 32'h1234_5678, 4'hF, 0, 0, 0);
        axi_write(4'h4, 32'h9ABC_DEF0, 4'hF, 0, 0, 0);
        axi_write(4'h8, 32'h0F1E_2D3C, 4'hF, 0, 0, 0);
        axi_write(4'hC, 32'hA5A5_5A5A, 4'hF, 0, 0, 0);
        read_all;

        // 3. Byte strobes: partial and empty
        axi_write(4'h8, 32'h1122_3344, 4'b0101, 0, 0, 0);
        axi_read(4'h8, 0);
        axi_write(4'h8, 32'hDEAD_BEEF, 4'b1000, 0, 0, 0);
        axi_read(4'h8, 0);
        axi_write(4'h4, 32'hCAFE_0000, 4'b0010, 0, 0, 0);
        axi_read(4'h4, 0);
        axi_write(4'hC, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);
        axi_read(4'hC, 0);

        // 4. AW/W ordering
        axi_write(4'h4, 32'h1111_2222, 4'hF, 1, 3, 0);
        axi_write(4'h8, 32'h3333_4444, 4'hF, 2, 2, 0);
        axi_write(4'h0, 32'h5555_6666, 4'hF, 0, 0, 0);
        axi_write(4'hC, 32'h7777_8888, 4'hF, 1, 1, 0);
        axi_write(4'h0, 32'h0000_00AA, 4'b0001, 2, 1, 0);
        read_all;

        // 5. Back-pressure on B and R
        axi_write(4'h0, 32'h5555_AAAA, 4'hF, 0, 0, 4);
        axi_read(4'h0, 5);
        axi_write(4'h4, 32'h0123_4567, 4'hF, 2, 2, 3);
        axi_read(4'h4, 1);
        axi_write(4'h8, 32'h89AB_CDEF, 4'hF, 1, 2, 1);
        axi_read(4'h8, 3);

        // 6. Back-to-back transactions
        axi_write(4'h0, 32'hB2B0_0000, 4'hF, 0, 0, 0);
        axi_write(4'h4, 32'hB2B1_1111, 4'hF, 0, 0, 0);
        axi_write(4'h8, 32'hB2B2_2222, 4'hF, 0, 0, 0);
        axi_write(4'hC, 32'hB2B3_3333, 4'hF, 0, 0, 0);
        read_all;
        read_all;

        // 7. SLVERR policy: unmapped writes change nothing, unmapped reads return 0
        axi_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
        axi_write(4'hE, 32'hEEEE_EEEE, 4'hF, 1, 2, 2);
        axi_write(4'h3, 32'h3333_3333, 4'hF, 2, 1, 0);
        axi_read(4'h6, 0);
        axi_read(4'hF, 2);
        axi_read(4'h1, 0);
        read_all;

        // 8. Reads and writes on the same clock
        fork
            axi_write(4'h0, 32'hC0C0_C0C0, 4'hF, 0, 0, 0);
            axi_read(4'hC, 0);
        join
        fork
            axi_write(4'h8, 32'hC8C8_C8C8, 4'hF, 2, 1, 2);
            axi_read(4'h4, 3);
        join
        fork
            axi_write(4'hD, 32'hDDDD_DDDD, 4'hF, 0, 0, 1);
            axi_read(4'h2, 1);
        join
        read_all;

        // 9. Reset while B and R are pending
        s_axil_bready  = 1'b0;
        s_axil_rready  = 1'b0;
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h4;
        s_axil_wvalid  = 1'b1;
        s_axil_wdata   = 32'h7777_8888;
        s_axil_wstrb   = 4'hF;
        s_axil_arvalid = 1'b1;
        s_axil_araddr  = 4'h8;
        #1;
        `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "reset test: requests accepted")
        @(posedge aclk);
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_wvalid  = 1'b0;
        s_axil_arvalid = 1'b0;
        `CHECK(s_axil_bvalid && s_axil_rvalid, "reset test: B and R pending")
        @(negedge aclk);
        `CHECK(s_axil_bvalid && s_axil_rvalid, "reset test: B and R held under back-pressure")
        do_reset(2);
        read_all;

        // 10. Reset discards a half-accepted write (AW without W)
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h8;
        #1;
        `CHECK(s_axil_awready, "half write: AW accepted")
        @(posedge aclk);
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_awaddr  = 4'h0;
        `CHECK(!s_axil_awready && s_axil_wready && !s_axil_bvalid, "half write: AW held and W awaited")
        do_reset(2);
        axi_write(4'h8, 32'hCAFE_F00D, 4'hF, 2, 3, 0);

        // 11. Reset discards a half-accepted write (W without AW)
        s_axil_wvalid = 1'b1;
        s_axil_wdata  = 32'hDEAD_DEAD;
        s_axil_wstrb  = 4'hF;
        #1;
        `CHECK(s_axil_wready, "half write: W accepted")
        @(posedge aclk);
        @(negedge aclk);
        s_axil_wvalid = 1'b0;
        s_axil_wdata  = 32'h0;
        s_axil_wstrb  = 4'h0;
        `CHECK(s_axil_awready && !s_axil_wready && !s_axil_bvalid, "half write: W held and AW awaited")
        repeat (3) begin
            @(negedge aclk);
            `CHECK(!s_axil_bvalid, "half write: no B without AW")
        end
        do_reset(1);
        axi_write(4'h4, 32'h0BAD_CAFE, 4'hF, 1, 2, 0);
        read_all;

        repeat (2) @(negedge aclk);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
